<template><section class="consult"><button class="back" @click="back">← 返回{{route.query.from==='personal'?'个人中心':reportId ? '体检报告':'首页'}}</button><h1>在线咨询</h1><p>提交问题后，可在此查看回复。医生可查看所关联的体检报告。急症请立即就医。</p><div class="consult-grid"><aside><h3>我的咨询</h3><button class="outline" @click="startNew">＋ 新建咨询</button><button v-for="t in threads" :key="t.consultationId" class="thread" @click="open(t.consultationId)">咨询 #{{t.consultationId}}<small>{{t.orderId ? '报告 #'+t.orderId : '健康咨询'}} · {{t.status==='WAITING'?'等待回复':'已回复'}}</small></button><p v-if="!threads.length">暂无咨询记录</p></aside><article><template v-if="!active"><h3>提交咨询</h3><p v-if="reportId">关联报告 #{{reportId}}</p><p v-else>您可以提出健康或体检相关问题。</p></template><template v-else><h3>咨询 #{{active.consultationId}}</h3><p>{{active.orderId ? '关联报告 #'+active.orderId : '健康咨询'}} · {{active.status==='WAITING'?'等待回复':'已回复'}}</p><div class="messages"><div v-for="m in messages" :key="m.messageId" class="message"><strong>{{m.senderType==='USER'?'我':'医生'}}</strong><small>{{format(m.createdAt)}}</small><p>{{m.content}}</p></div></div></template><form @submit.prevent="send"><label for="question">{{active?'继续提问':'您的问题'}}</label><textarea id="question" v-model.trim="text" required maxlength="1000" rows="5" placeholder="请描述您想咨询的问题"></textarea><button class="primary" :disabled="busy">{{busy?'提交中…':'提交问题'}}</button></form><p v-if="error" class="failure" role="alert">{{error}}</p></article></div></section></template>
<script setup>
import { ref, onMounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import axios from 'axios'
const route=useRoute(),router=useRouter(),threads=ref([]),active=ref(null),messages=ref([]),text=ref(''),error=ref(''),busy=ref(false), reportId=ref(Number(route.query.orderId)||null)
const api=axios.create({baseURL:'/tijian',timeout:10000})
async function call(path,data={}){try{return (await api.post('/consultations/'+path,data)).data}catch(e){if(e.response?.status===401){sessionStorage.removeItem('tijianUser');router.replace('/login')}throw e}}
function back(){if(route.query.from==='personal')router.push('/personal');else if(route.query.orderId)router.push({name:'report',query:{orderId:route.query.orderId}});else router.push('/home')}
const format=s=>String(s||'').replace('T',' ').slice(0,16)
async function list(){threads.value=await call('list')}
async function open(id){error.value='';try{const d=await call('messages',{consultationId:id});active.value=d.consultation;messages.value=d.messages;reportId.value=null}catch(e){error.value='无法加载咨询，请稍后重试。'}}
function startNew(){active.value=null;messages.value=[];reportId.value=null;text.value='';error.value=''}
async function send(){if(!text.value||busy.value)return;busy.value=true;error.value='';try{let id=active.value?.consultationId;if(id)await call('send',{consultationId:id,content:text.value});else id=(await call('create',{orderId:reportId.value,content:text.value})).consultationId;text.value='';await list();await open(id)}catch(e){error.value=e.response?.status===404?'报告不存在或无法访问。':'提交未完成，请检查服务后重试。'}finally{busy.value=false}}
onMounted(async()=>{try{await list()}catch(e){error.value='咨询列表加载失败。'}})
</script>
<style scoped>.consult>p,.consult article>p,.consult aside>p{color:#78938b;font-size:13px;line-height:1.7;margin:12px 0 20px}.consult-grid{display:grid;grid-template-columns:250px 1fr;gap:18px;margin-top:25px}.consult aside,.consult article{background:white;border:1px solid #e3eeeb;border-radius:14px;padding:24px}.consult aside h3,.consult article h3{margin-bottom:15px}.thread{display:block;width:100%;text-align:left;background:#f2f8f5;border:0;border-radius:8px;margin-top:10px;padding:12px;color:#204c42}.thread small{display:block;margin-top:6px;color:#77938b}.messages{max-height:400px;overflow:auto}.message{background:#f4f9f6;padding:14px;margin:12px 0;border-radius:9px;white-space:pre-wrap;overflow-wrap:anywhere}.message small{color:#8ea69f;margin-left:12px}.message p{margin-top:8px;line-height:1.6}.consult form{display:grid;gap:10px;margin-top:20px}.consult textarea{width:100%;padding:12px;border:1px solid #d9e8e1;border-radius:8px;resize:vertical;font:inherit}.consult form button{justify-self:start}.failure{color:#b14b42!important}@media(max-width:700px){.consult-grid{grid-template-columns:1fr}}</style>